package edu.pbs.hub.repo; import edu.pbs.hub.model.Paper; import org.springframework.data.jpa.repository.JpaRepository; import java.util.*; public interface PaperRepository extends JpaRepository<Paper,Long>{ List<Paper> findByCourseIdAndSemesterAndCategoryAndYearOrderBySubjectAsc(Long courseId,Integer semester,String category,Integer year); List<Paper> findByCourseIdAndSemesterOrderByYearDesc(Long courseId,Integer semester); List<Paper> findByCourseIdOrderByYearDesc(Long courseId); List<Paper> findBySubjectContainingIgnoreCaseOrDescriptionContainingIgnoreCase(String subject,String description); }
